CREATE TABLE IF NOT EXISTS execution_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), workflow_id uuid NOT NULL REFERENCES workflows(id), status varchar(40) NOT NULL, idempotency_key varchar(200) NOT NULL, correlation_id varchar(200) NOT NULL, started_at timestamptz, finished_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT execution_runs_idempotency_unique UNIQUE (tenant_id, idempotency_key));
CREATE INDEX IF NOT EXISTS execution_runs_workflow_idx ON execution_runs(tenant_id, workflow_id);
CREATE TABLE IF NOT EXISTS execution_steps (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), execution_run_id uuid NOT NULL REFERENCES execution_runs(id), task_id uuid NOT NULL REFERENCES tasks(id), execution_id varchar(200) NOT NULL, status varchar(40) NOT NULL, attempt_number integer NOT NULL DEFAULT 1, correlation_id varchar(200) NOT NULL, started_at timestamptz, finished_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT execution_steps_execution_unique UNIQUE (tenant_id, execution_id));
CREATE INDEX IF NOT EXISTS execution_steps_task_idx ON execution_steps(tenant_id, task_id);
CREATE TABLE IF NOT EXISTS provider_calls (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), execution_id varchar(200) NOT NULL, provider varchar(80) NOT NULL, model varchar(120) NOT NULL, status varchar(40) NOT NULL, idempotency_key varchar(200) NOT NULL, correlation_id varchar(200) NOT NULL, requested_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, CONSTRAINT provider_calls_idempotency_unique UNIQUE (tenant_id, idempotency_key));
CREATE INDEX IF NOT EXISTS provider_calls_execution_idx ON provider_calls(tenant_id, execution_id);
CREATE TABLE IF NOT EXISTS provider_usage (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), provider_call_id uuid NOT NULL REFERENCES provider_calls(id), input_tokens integer NOT NULL, output_tokens integer NOT NULL, total_tokens integer NOT NULL, estimated_cost text NOT NULL, currency varchar(3) NOT NULL DEFAULT 'USD', recorded_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS provider_usage_tenant_idx ON provider_usage(tenant_id, provider_call_id);
CREATE TABLE IF NOT EXISTS retry_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), execution_step_id uuid NOT NULL REFERENCES execution_steps(id), attempt_number integer NOT NULL, reason text NOT NULL, retryable boolean NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT retry_attempts_unique UNIQUE (execution_step_id, attempt_number));
CREATE INDEX IF NOT EXISTS retry_attempts_tenant_idx ON retry_attempts(tenant_id);
CREATE TABLE IF NOT EXISTS workflow_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), workflow_id uuid NOT NULL REFERENCES workflows(id), task_id uuid REFERENCES tasks(id), execution_id varchar(200), event_type varchar(120) NOT NULL, correlation_id varchar(200) NOT NULL, payload jsonb NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS workflow_events_tenant_workflow_idx ON workflow_events(tenant_id, workflow_id, occurred_at);
CREATE INDEX IF NOT EXISTS workflow_events_execution_idx ON workflow_events(tenant_id, execution_id);
CREATE TABLE IF NOT EXISTS execution_errors (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), execution_id varchar(200) NOT NULL, workflow_id uuid NOT NULL REFERENCES workflows(id), task_id uuid REFERENCES tasks(id), code varchar(80) NOT NULL, message text NOT NULL, retryable boolean NOT NULL, correlation_id varchar(200) NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS execution_errors_tenant_execution_idx ON execution_errors(tenant_id, execution_id);